/* M04 Penarikan — same account, same ledger, across label / admin / super admin. */
const ui108={tab:'all',q:'',detail:null};
const B108=(text,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-w108="${action}" data-id="${E(id)}">${text}</button>`;
const names108={requested:['Menunggu pemeriksaan','Awaiting review'],ready:['Menunggu pembayaran','Awaiting payment'],processing:['Pembayaran diproses','Payment in progress'],delayed:['Ditunda','Deferred'],paid:['Dibayarkan','Paid'],correction:['Koreksi pembayaran','Payment correction']};
const actionNames108={request:'Pengajuan diterima',approve:'Penarikan disetujui',start:'Pembayaran dimulai',paid:'Pembayaran dikonfirmasi',delay:'Pembayaran ditunda',resume:'Pembayaran dilanjutkan',bank:'Rekening pengajuan diperbarui','resolve-success':'Transfer dipastikan berhasil','resolve-failed':'Transfer dipastikan gagal',correction:'Koreksi pembayaran diajukan','correction-keep':'Pembayaran tetap dikonfirmasi','correction-reopen':'Pembayaran dikembalikan untuk diproses'};
function model108(){const r=model107(),s=Withdraw108.init(r);if(!s.accounts.length){const groups=(data.v9?.labels||[]).filter(l=>l.master).map(l=>{const m=ten.members.find(m=>m.source9===l.id);return m?{id:m.id,name:m.name,members:[m.id,...(l.children||[]).map(c=>ten.members.find(m=>m.source9===c.id)?.id).filter(Boolean)],master:true}:null}).filter(Boolean);const children=new Set(groups.flatMap(a=>a.members.slice(1)));s.accounts=[...groups,...ten.members.filter(m=>!children.has(m.id)&&!groups.some(a=>a.id===m.id)).map(m=>({id:m.id,name:m.name,members:[m.id],master:false}))]}const accounted=new Set(s.accounts.flatMap(a=>a.members));for(const m of ten.members)if(!accounted.has(m.id))s.accounts.push({id:m.id,name:m.name,members:[m.id],master:false});for(const a of s.accounts){const m=RM10.getMember(ten,a.id);if(m)a.name=m.name}return s}
function account108(){model108();return Withdraw108.owner(model107(),ten.member)}
function context108(a){const m=RM10.getMember(ten,a.id);return {at:ten.now,bank:m?.bank?.approved||null,city:m?.identity?.location?.cityName||m?.identity?.location?.regencyName||m?.identity?.location?.regency||m?.identity?.location?.city||m?.identity?.city||'—'}}
function can108(){return isLabel10()||ten.role==='super'||allowedModule(modules.find(m=>m.id==='withdraw'))}
function act108(action,p){if(!can108())throw Error('Akses tidak tersedia.');if(ten.role==='admin'&&['read','blocked'].includes(access8(p.id)))throw Error('Akses tindakan belum tersedia pada sesi ini.');return atomic10(()=>{pendingInit();const s=model108(),r=model107(),w=s.requests.find(w=>w.id===p.id),a=Withdraw108.account(r,w?.account||p.account);const result=Withdraw108.act(r,{role:ten.role,member:ten.member,id:isLabel10()?ten.member:state.user},action,p,context108(a));reconcilePayoutAchievements116();return result})}
function route108(id=null){closeModal();document.querySelector('#royalty-drawer107')?.close();ui108.detail=id;state.page='module';state.mode='platform';v4.module='withdraw';render();window.scrollTo({top:0,behavior:'instant'})}
function list108(){const s=model108();return s.requests.filter(w=>!isLabel10()||w.account===ten.member)}
function state108(w){return pill107(T(...names108[w.status]),w.status==='paid'?'green':['delayed','correction'].includes(w.status)?'amber':'')+(w.uncertain?pill107(T('Perlu konfirmasi','Needs confirmation'),'amber'):'')+(Withdraw108.overdue(w,ten.now)?pill107(T('Lewat tenggat','Overdue'),'red'):'')}
function period108(ps){return ps.length?month107(ps[0])+(ps.length>1?' – '+month107(ps.at(-1)):''):T('Belum ada periode','No reporting period')}
function copy108(label,value,mask){return `<div class="copy108"><div><small>${label}</small><strong>${E(mask??value)}</strong></div><button class="copy-button108" data-w108="copy" data-id="${E(value)}" aria-label="${T('Salin','Copy')} ${label}" title="${T('Salin','Copy')}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="8" y="8" width="12" height="13" rx="3"/><path d="M15 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h3"/></svg></button></div>`}
function bank108(bank,full=false){if(!bank)return `<div class="bank-card108"><small>${T('Rekening penerima','Payout account')}</small><h3>${T('Belum disetujui','Not approved yet')}</h3>${B108(T('Lihat rekening','View bank details'),'profile')}</div>`;return `<div class="bank-card108"><span class="bank-chip108" aria-hidden="true">▥</span><small>${E(bank.bank)}</small><strong class="account-number108">${E(full?bank.number:'•••• '+String(bank.number).slice(-4))}</strong><footer><span>${E(bank.holder)}</span><span>✓ ${T('Disetujui','Approved')}</span></footer></div>`}
function balances108(a){const b=Withdraw108.totals(model107(),a.id);return `<div class="balances108">${[[T('Saldo tersedia','Available balance'),b.available,'available'],[T('Dalam penarikan','Withdrawal in progress'),b.processing,'processing'],[T('Menunggu dana masuk','Awaiting funds'),b.pending,'pending']].map(([title,n,id],i)=>`<article class="balance-card108 ${i===0?'brand108':''}" data-balance108="${id}"><small>${title}</small><strong>${money107(n)}</strong><span>${i===0?T('Minimal penarikan Rp1.000.000','Minimum withdrawal IDR 1,000,000'):i===1?T('Tersimpan pada pengajuan berjalan','Reserved in the current request'):T('Belum tersedia untuk ditarik','Not available to withdraw yet')}</span></article>`).join('')}</div>`}
function attention108(w){const overdue=Withdraw108.overdue(w,ten.now);if(!['delayed','correction'].includes(w.status)&&!w.uncertain&&!overdue)return '';return `<section class="attention9 attention108 ${overdue?'red9':''}"><div><h3>${w.uncertain?T('Hasil transfer sedang diperiksa','Transfer result under review'):w.status==='delayed'?T('Pembayaran ditunda','Payment deferred'):w.status==='correction'?T('Pencatatan pembayaran sedang diperiksa','Payment record under review'):T('Pembayaran melewati tenggat','Payment overdue')}</h3><p>${E(w.message||T('Pengajuanmu tetap tersimpan dan menunggu penyelesaian petugas.','Your request remains saved and awaits staff resolution.'))}</p></div>${isLabel10()&&w.reason==='bank'?B108(T('Perbaiki rekening','Correct bank details'),'profile'):B108(T('Lihat pengajuan','View request'),'detail',w.id,'text')}</section>`}
function labelWithdraw108(){const a=account108();if(!a||a.id!==ten.member)return `<section class="panel107">${empty107(T('Penarikan saldo label ini dikelola melalui akun master.','Withdrawals for this label are handled by the master account.'))}</section>`;const r=model107(),ctx=context108(a),bal=Withdraw108.totals(r,a.id),active=list108().find(w=>w.status!=='paid'),why=Withdraw108.reason(r,a.id,ctx.bank,ten.now);return `<div class="royalty107 withdrawal108"><header class="head107"><div><span class="eyebrow107">ROYALTY PAYOUT</span><h1>${T('Penarikan','Withdrawals')}</h1><p>${a.master?T('Satu saldo dari seluruh label yang kamu kelola.','One balance across all your managed labels.'):T('Kelola pencairan pendapatan katalogmu.','Manage your catalogue payouts.')}</p></div></header>${balances108(a)}${active?attention108(active):''}<div class="payout-grid108"><section class="panel107 request-card108"><small class="eyebrow107">${active?active.id:T('PENGAJUAN PENARIKAN','WITHDRAWAL REQUEST')}</small><h2>${active?T(...names108[active.status]):T('Tarik saldo royalti','Withdraw your royalties')}</h2><strong class="payout-amount108">${money107(active?.amount??bal.available)}</strong><p>${active?T('Nominal pengajuan tetap. Pendapatan baru terkumpul di saldo tersedia.','The requested amount is fixed. New earnings accumulate separately.'):T('Seluruh saldo tersedia akan diajukan dalam satu penarikan.','Your entire available balance is included in one withdrawal.')}</p>${active?`${state108(active)}<div class="actions107">${B108(T('Lihat pengajuan','View request'),'detail',active.id,'primary')}</div>`:`<p class="note107">${E(why||T('Pengajuan 1–14 setiap bulan · Pembayaran 15–20.','Requests: 1–14 each month · Payments: 15–20.'))}</p><button class="btn primary" data-w108="request" ${why?'disabled':''}>${T('Ajukan penarikan','Request withdrawal')} ↗</button>${!ctx.bank?B108(T('Lengkapi rekening','Complete bank details'),'profile','','text'):''}`}</section><section class="panel107"><h2>${T('Rekening penerima','Payout account')}</h2>${bank108(ctx.bank)}<p>${T('Pembayaran dikirim ke rekening yang disetujui untuk akun ini.','Payments go to the approved account bank details.')}</p></section></div>${history108()}</div>`}
function history108(){const rows=list108().slice().reverse();return `<section class="panel107"><div class="head107"><h2>${T('Riwayat penarikan','Withdrawal history')}</h2><small>${rows.length} ${T('pengajuan','requests')}</small></div><div class="table107"><table><thead><tr>${[T('Pengajuan','Request'),T('Periode royalti','Royalty period'),T('Nominal','Amount'),'Status',''].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(w=>`<tr><td><strong>${w.id}</strong><small>${date107(w.created)}</small></td><td>${period108(w.periods)}</td><td>${money107(w.amount)}</td><td>${state108(w)}</td><td>${B108('↗','detail',w.id,'arrow107')}</td></tr>`).join('')||`<tr><td colspan="5">${empty107(T('Belum ada pengajuan penarikan.','No withdrawal requests yet.'))}</td></tr>`}</tbody></table></div></section>`}
function staffWithdraw108(){const rows=list108().filter(w=>(ui108.tab==='all'||ui108.tab==='attention'&&(['delayed','correction'].includes(w.status)||w.uncertain||Withdraw108.overdue(w,ten.now))||ui108.tab==='payment'&&['ready','processing'].includes(w.status)||w.status===ui108.tab)&&(!ui108.q||[w.name,w.id,w.bank.bank].join(' ').toLowerCase().includes(ui108.q.toLowerCase())));const all=list108();return `<div class="royalty107 withdrawal108"><header class="head107"><div><span class="eyebrow107">PAYMENT OPERATIONS</span><h1>${T('Penarikan','Withdrawals')}</h1><p>${T('Periksa pengajuan. Pastikan setiap pembayaran terselesaikan.','Review requests. Keep every payment moving to completion.')}</p></div></header><div class="balances108">${[['requested','Menunggu pemeriksaan','Awaiting review'],['ready','Siap dibayar','Ready to pay'],['attention','Perlu perhatian','Needs attention']].map(([id,a,b],i)=>{const rs=all.filter(w=>id==='attention'?['delayed','correction'].includes(w.status)||w.uncertain||Withdraw108.overdue(w,ten.now):w.status===id);return `<article class="balance-card108 ${i===0?'brand108':''}"><small>${T(a,b)}</small><strong>${rs.length}</strong><span>${money107(rs.reduce((n,w)=>n+w.amount,0))}</span></article>`}).join('')}</div><nav class="tabs" data-switch-key105="withdraw-tabs108">${[['all','Semua','All'],['requested','Pemeriksaan','Review'],['payment','Daftar pembayaran','Payment list'],['attention','Perlu perhatian','Needs attention'],['paid','Dibayarkan','Paid']].map(([id,a,b])=>B108(T(a,b),'tab',id,ui108.tab===id?'active':'')).join('')}</nav><div class="toolbar107"><input type="search" id="search108" placeholder="${T('Cari nama akun, bank, atau pengajuan','Search account, bank or request')}" value="${E(ui108.q)}"><small>${rows.length} ${T('pengajuan','requests')}</small></div><div class="payment-list108">${rows.map(w=>paymentRow108(w)).join('')||`<section class="panel107">${empty107(T('Tidak ada pengajuan pada daftar ini.','No requests in this list.'))}</section>`}</div></div>`}
function paymentRow108(w){return `<article class="panel107 payment-row108"><header><div><small>${w.id} · ${T('Periode royalti','Royalty period')}: ${period108(w.periods)}</small><div class="states108">${state108(w)}</div></div>${B108('↗','detail',w.id,'arrow107')}</header><div class="payment-fields108">${copy108(T('Nama akun','Account name'),w.name)}${copy108(T('Kota/kabupaten','City / regency'),w.city)}<div>${copy108(T('Bank tujuan','Destination bank'),w.bank.bank)}${ten.role==='super'?copy108(T('Nomor rekening','Account number'),w.bank.number):`<small>•••• ${E(String(w.bank.number).slice(-4))}</small>`}${copy108(T('Nama penerima','Recipient name'),w.bank.holder)}</div>${copy108(T('Nominal','Amount'),String(w.amount),money107(w.amount))}${copy108(T('Keterangan','Description'),w.memo)}</div>${w.message?`<p class="note107">${E(w.message)}</p>`:''}<footer>${staffActions108(w)}</footer></article>`}
function staffActions108(w){if(isLabel10())return '';let actions='';if(w.status==='requested')actions+=B108(T('Setujui penarikan','Approve withdrawal'),'approve',w.id,'primary');if(ten.role==='super'){if(w.status==='ready')actions+=B108(T('Mulai pembayaran','Start payment'),'start',w.id,'primary');if(w.status==='processing'&&!w.uncertain&&w.handler===state.user)actions+=B108(T('Konfirmasi pembayaran','Confirm payment'),'paid',w.id,'primary');if(w.status==='processing'&&w.uncertain)actions+=B108(T('Periksa hasil transfer','Check transfer result'),'resolve',w.id,'primary');if(w.status==='delayed'){actions+=B108(T('Lanjutkan pembayaran','Resume payment'),'resume',w.id,'primary');if(w.reason==='bank'||Withdraw108.fingerprint(w.bank)!==Withdraw108.fingerprint(context108(Withdraw108.account(model107(),w.account)).bank))actions+=B108(T('Tinjau rekening terbaru','Review latest bank details'),'bank',w.id)}if(w.status==='paid')actions+=B108(T('Ajukan koreksi pembayaran','Request payment correction'),'correction',w.id,'text');if(w.status==='correction')actions+=B108(T('Selesaikan pemeriksaan','Resolve review'),'resolve-correction',w.id,'primary')}
 if(['requested','ready','processing'].includes(w.status)&&!w.uncertain&&(ten.role==='super'||w.status!=='processing'))actions+=B108(T('Tunda pembayaran','Defer payment'),'delay',w.id,'text');return actions}
function detail108(w){const own=isLabel10();return `<div class="royalty107 withdrawal108">${B108('← '+T('Penarikan','Withdrawals'),'back','','text')}<header class="head107"><div><span class="eyebrow107">${w.id}</span><h1>${E(w.name)}</h1><p>${T('Diajukan pada','Requested on')} ${date107(w.created)}</p></div><div class="states108">${state108(w)}</div></header>${attention108(w)}<div class="payout-grid108"><section class="panel107"><small>${T('Nominal penarikan','Withdrawal amount')}</small><strong class="payout-amount108">${money107(w.amount)}</strong><p>${T('Periode royalti','Royalty period')}: ${period108(w.periods)}</p><div class="step108">${['requested','ready','processing','paid'].map((s,i)=>`<span class="${['requested','ready','processing','paid'].indexOf(w.status)>=i?'done':''}"><i>${i+1}</i>${T(...names108[s])}</span>`).join('')}</div>${!own?`<div class="actions107">${staffActions108(w)}${ten.role==='super'&&w.reason==='bank'?B108(T('Periksa rekening label','Review label bank account'),'bank-review',w.account,'text'):''}</div>`:''}${w.paid?`<p>${T('Dicatat dibayarkan pada','Recorded as paid on')} ${date107(w.paid)}</p>`:''}</section><section class="panel107"><h2>${T('Rekening pengajuan','Request bank details')}</h2>${bank108(w.bank,ten.role==='super')}${!own?copy108(T('Keterangan transfer','Transfer description'),w.memo):''}<p>${T('Rekening tersimpan pada pengajuan ini. Perubahan profil tidak menggantinya secara otomatis.','Bank details are saved with this request. Profile updates do not replace them automatically.')}</p></section></div><section class="panel107"><h2>${T('Riwayat proses','Process history')}</h2>${w.events.filter(e=>!e.internal).slice().reverse().map(e=>`<div class="history107"><div><strong>${E(actionNames108[e.action]||e.action)}</strong><p>${E(own?e.message:e.note||e.message)}</p><small>${date107(e.at)}${own?'':' · '+E(people.find(p=>p.id===e.actor)?.name||e.actor)}</small></div></div>`).join('')}</section></div>`}
function page108(){if(!can108())return empty107(T('Menu tidak tersedia.','Menu unavailable.'));model108();const w=ui108.detail&&list108().find(w=>w.id===ui108.detail);return w?detail108(w):isLabel10()?labelWithdraw108():staffWithdraw108()}
function form108(title,action,w,body,button){reviewDialogUI(title,`<form class="form107 payout-form108" data-form108="${action}" data-id="${w?.id||''}" data-version="${model108().version}">${body}<p class="error108" role="alert"></p><div class="actions107">${B108(T('Kembali','Back'),'close','','text')}<button class="btn primary" type="submit">${button||T('Simpan','Save')}</button></div></form>`)}
function dialog108(action,id){const w=id?list108().find(w=>w.id===id):null;if(id&&!w)return;const note=`<label>${T('Catatan pemeriksaan internal','Internal review note')}<textarea name="note" required rows="3"></textarea></label>`;
 if(action==='request'){const a=account108(),ctx=context108(a),b=Withdraw108.totals(model107(),a.id);form108(T('Konfirmasi pengajuan','Confirm request'),'request',null,`<input type="hidden" name="account" value="${a.id}"><input type="hidden" name="amount" value="${b.available}"><input type="hidden" name="bankFingerprint" value="${E(Withdraw108.fingerprint(ctx.bank))}"><strong class="payout-amount108">${money107(b.available)}</strong>${bank108(ctx.bank)}<p>${T('Seluruh saldo tersedia akan diajukan. Pembayaran dijadwalkan tanggal 15–20 bulan ini. Pengajuan tidak dapat dibatalkan.','Your entire available balance will be requested. Payment is scheduled for the 15th–20th this month. Requests cannot be cancelled.')}</p>`,T('Konfirmasi pengajuan','Confirm request'));return}
 if(['approve','start','paid','resume'].includes(action)){const titles={approve:T('Setujui penarikan','Approve withdrawal'),start:T('Mulai pembayaran','Start payment'),paid:T('Konfirmasi pembayaran','Confirm payment'),resume:T('Lanjutkan pembayaran','Resume payment')};form108(titles[action],action,w,`<strong class="payout-amount108">${money107(w.amount)}</strong><p>${E(w.name)} · ${E(w.bank.bank)} ••••${E(String(w.bank.number).slice(-4))}</p><p>${action==='paid'?T('Pastikan transfer telah berhasil di website bank.','Make sure the transfer succeeded on the bank website.'):action==='start'?T('Pengajuan akan ditandai sedang kamu tangani. Lanjutkan transfer melalui website bank.','This request will be assigned to you. Continue the transfer on the bank website.'):action==='resume'?T('Pastikan kendala telah selesai. Nominal pengajuan tetap tersimpan.','Make sure the issue has been resolved. The requested amount stays reserved.'):T('Periksa nominal dan rekening sebelum menyetujui pengajuan.','Review the amount and bank details before approving.')}</p>`,action==='paid'?T('Pembayaran berhasil','Payment successful'):titles[action]);return}
 if(action==='delay')form108(T('Tunda pembayaran','Defer payment'),'delay',w,`<label>${T('Alasan penundaan','Reason')}<select name="reason" id="delay-reason108"><option value="bank">${T('Kendala rekening','Bank account issue')}</option><option value="service">${T('Kendala layanan bank','Bank service issue')}</option><option value="uncertain">${T('Hasil transfer belum pasti','Transfer result uncertain')}</option><option value="other">${T('Kendala lainnya','Other issue')}</option></select></label><label>${T('Pesan kepada label','Message to the label')}<textarea name="message" required rows="3">${T('Rekening penerima perlu diperiksa. Silakan periksa informasi rekeningmu.','The recipient account needs review. Please check your bank details.')}</textarea></label><label>${T('Catatan internal (opsional)','Internal note (optional)')}<textarea name="note" rows="2"></textarea></label>${w.status==='processing'?`<label class="check108"><input type="checkbox" name="failed">${T('Untuk menunda selain hasil belum pasti: transfer belum dilakukan atau telah dipastikan gagal.','For other deferrals: no transfer was made or it is confirmed failed.')}</label>`:''}`,T('Simpan penundaan','Save deferral'));
 if(action==='resolve')form108(T('Periksa hasil transfer','Check transfer result'),'resolve',w,`<label>${T('Hasil pemeriksaan','Review result')}<select name="result"><option value="resolve-success">${T('Transfer berhasil','Transfer succeeded')}</option><option value="resolve-failed">${T('Transfer dipastikan gagal','Transfer confirmed failed')}</option></select></label>${note}`,T('Konfirmasi hasil pemeriksaan','Confirm review result'));
 if(action==='correction')form108(T('Ajukan koreksi pembayaran','Request payment correction'),'correction',w,`<p>${T('Koreksi membuka pemeriksaan. Saldo tidak dikembalikan dan transfer ulang tetap ditahan.','A correction opens a review. Funds are not released and another transfer stays blocked.')}</p>${note}`,T('Ajukan koreksi','Request correction'));
 if(action==='resolve-correction')form108(T('Selesaikan pemeriksaan','Resolve review'),'resolve-correction',w,`<label>${T('Hasil pemeriksaan','Review result')}<select name="result"><option value="correction-keep">${T('Pembayaran dipastikan berhasil','Payment confirmed successful')}</option><option value="correction-reopen">${T('Transfer tidak terjadi atau gagal','Transfer did not occur or failed')}</option></select></label>${note}<label class="check108"><input type="checkbox" name="failed">${T('Jika dibuka kembali: saya memastikan uang belum terkirim atau transfer telah gagal.','If reopening: I confirm funds were not sent or the transfer failed.')}</label>`,T('Simpan hasil pemeriksaan','Save review result'));
 if(action==='bank'){const bank=context108(Withdraw108.account(model107(),w.account)).bank;form108(T('Tinjau rekening terbaru','Review latest bank details'),'bank',w,`<p>${T('Rekening pada pengajuan','Bank details on the request')}: ${E(w.bank.bank)} ••••${E(String(w.bank.number).slice(-4))}</p>${bank108(bank,true)}<p>${T('Gunakan hanya rekening yang sudah disetujui. Rekening sebelumnya tetap tersimpan dalam riwayat.','Only use approved bank details. Previous details remain in the audit history.')}</p>${note}`,T('Gunakan rekening yang disetujui','Use approved bank details'))}
}
const moduleBase108=modulePage;modulePage=function(){if(v4.module==='withdraw')return page108();return moduleBase108()};
const handleBase108=handleAction;handleAction=async function(b){if(b.dataset.action==='v4-module'&&b.dataset.id==='withdraw')return route108();return handleBase108(b)};
const safeBase108=safeRows107;safeRows107=function(){if(isLabel10()){const a=account108();if(a?.master)return Royalty107.rows(model107(),{}).filter(r=>a.members.includes(r.member));}return safeBase108()};
const balanceBase108=Royalty107.balance;Royalty107.balance=function(r,id){const a=r.withdraw108?.accounts.find(a=>a.id===id);if(a)return Withdraw108.totals(r,id);return balanceBase108(r,id)};
