const homeBase108=labelHome102;labelHome102=function(){let html=homeBase108();const a=account108();if(a?.id===ten.member){const el=document.createElement('div');el.innerHTML=html;const anchor=el.querySelector('.dashboard-grid');if(anchor){const active=list108().find(w=>w.status!=='paid');anchor.insertAdjacentHTML('beforebegin',`<section class="royalty107 home-balance108"><div class="head107"><h2>${T('Saldo royalti','Royalty balance')}</h2>${B108(T('Penarikan','Withdrawals')+' ↗','route','','text')}</div>${balances108(a)}${active?attention108(active):''}</section>`);html=el.innerHTML}}return html};
